styles./assets/member-experience/my-shift.css:
html:has(#my-shift),body:has(#my-shift){margin:0;background:#050505;color:#e7e3da;font:14px/1.5 Arial,Helvetica,sans-serif;color-scheme:light}
#my-shift{--ink:#050505;--cream:#e7e3da;--green:#707762;--muted:#545b49;max-width:1240px;margin:auto;background:var(--ink);color:var(--cream)}
#my-shift *{box-sizing:border-box}#my-shift [hidden]{display:none!important}#my-shift :is(h1,h2,h3,p){margin:0}#my-shift :is(p,a,strong,small,dd){overflow-wrap:anywhere}#my-shift a{color:inherit;text-underline-offset:4px}
#my-shift button,#my-shift .ms-link{font:inherit;min-height:44px;padding:10px 14px;border:1px solid var(--green);border-radius:6px;background:var(--ink);color:var(--cream);cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;gap:8px}
#my-shift button:disabled{opacity:.6;cursor:wait}#my-shift :is(a,button,input):focus-visible{outline:3px solid #9aaa84;outline-offset:3px}
#my-shift .ms-skip{position:absolute;left:-10000px}#my-shift .ms-skip:focus{left:16px;top:8px;background:var(--cream);color:var(--ink);padding:12px;z-index:5}
#my-shift .ms-top{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:26px}#my-shift .ms-logo{font-size:20px;font-weight:900;letter-spacing:-.6px;text-decoration:none}#my-shift .ms-logo span{color:#adb69b}#my-shift .ms-logo small{display:block;font-size:11px;font-weight:400;letter-spacing:1.5px;margin-top:8px;color:#bdc5af}
#my-shift .ms-layout{display:grid;grid-template-columns:200px minmax(0,1fr)}#my-shift .ms-sidebar{padding:26px 14px;display:flex;flex-direction:column;gap:24px;border-right:1px solid #343a2b}#my-shift .ms-sidebar>strong{padding:0 12px}#my-shift nav{display:flex;flex-direction:column;gap:5px}#my-shift nav button{justify-content:flex-start;text-align:left;background:transparent;color:var(--cream);border:0;width:100%}#my-shift nav button[aria-current]{background:var(--green)}#my-shift #ms-nav-count{margin-left:auto;border-radius:4px;padding:1px 7px;background:var(--cream);color:var(--ink)}#my-shift .ms-sidebar-help{margin-top:auto;border-top:1px solid #343a2b;padding:18px 12px;color:#bdc5af;font-size:12px}#my-shift .ms-sidebar-help p{margin:7px 0}
#my-shift .ms-main{padding:28px;min-width:0}#my-shift .ms-toolbar{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:16px}#my-shift #ms-breadcrumb{font-size:11px;font-weight:700;letter-spacing:1.6px;color:#bdc5af}#my-shift #ms-status{font-size:12px;color:#bdc5af;margin-bottom:18px}
#my-shift .ms-panel{background:var(--cream);color:var(--ink);padding:28px;border-radius:10px;min-width:0}#my-shift h1{font-size:29px;line-height:1.2;letter-spacing:-1px;margin:0 0 8px}#my-shift h2{font-size:17px;line-height:1.3;letter-spacing:-.3px}#my-shift h3{font-size:15px}#my-shift .ms-lead{color:var(--muted);margin-bottom:24px}#my-shift .ms-heading{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;margin:24px 0 14px}#my-shift .ms-heading button{background:transparent;color:#465637;border:0;padding:4px 0;text-decoration:underline;text-underline-offset:4px}
#my-shift .ms-counts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:20px 0 24px}#my-shift .ms-stat{border:1px solid #bfc4b3;border-radius:9px;padding:20px;min-width:0}#my-shift .ms-stat strong{display:block;font-size:25px;margin:6px 0}#my-shift .ms-stat span,#my-shift .ms-stat small{color:var(--muted);font-size:12px}
#my-shift .ms-card{padding:22px;border:1px solid #bfc4b3;border-radius:9px;margin:16px 0;background:var(--cream);color:var(--ink)}#my-shift .ms-card p{margin:10px 0;color:var(--muted)}#my-shift .ms-card .ms-link{margin-top:10px}#my-shift .ms-cardhead{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:14px}#my-shift .ms-badge{font-size:11px;padding:5px 8px;border-radius:4px;background:#dce2d2;color:#344329}
#my-shift .ms-attention{background:var(--green);color:var(--cream);border:1px solid var(--green);background-clip:border-box;animation:my-shift-pulse 3s ease-in-out infinite}#my-shift .ms-attention :is(p,span,small){color:var(--cream)}#my-shift .ms-attention .ms-link{background:var(--cream);color:var(--ink);border-color:var(--cream)}#my-shift[data-motion=paused] .ms-attention{animation:none}
@keyframes my-shift-pulse{0%,100%{box-shadow:inset 0 0 0 2px #566046}50%{box-shadow:inset 0 0 0 3px #aab699}}
@media(prefers-reduced-motion:reduce){#my-shift .ms-attention{animation:none}}
#my-shift .ms-timeline{list-style:none;padding:0;margin:16px 0}#my-shift .ms-timeline li{border-left:2px solid #bfc4b3;padding:0 0 20px 16px}#my-shift .ms-timeline small{display:block;margin-top:4px;font-size:12px;color:var(--muted)}#my-shift .ms-note{padding:16px;background:#dce2d2;border-radius:6px;margin:16px 0}#my-shift dl{display:grid;grid-template-columns:1fr 1fr;gap:8px 16px;margin:16px 0}#my-shift dt{color:var(--muted)}#my-shift dd{margin:0}#my-shift .ms-footer{display:flex;flex-wrap:wrap;gap:18px;padding:28px;color:#bdc5af;font-size:12px}#my-shift #ms-motion{margin-top:18px}#my-shift #ms-menu-toggle{display:none}#my-shift #memberDetailsPanel{padding:0;margin:0;border:0;max-width:none;background:var(--cream);color:var(--ink)}#my-shift #memberDetailsPanel .md-heading{display:none}#my-shift #memberDetailsPanel .md-notice{margin-top:0}
@media(max-width:760px){#my-shift .ms-layout{grid-template-columns:170px minmax(0,1fr)}#my-shift .ms-main{padding:22px}#my-shift .ms-two{display:block}}
@media(max-width:540px){#my-shift .ms-top{padding:20px;flex-wrap:wrap}#my-shift .ms-layout{display:block}#my-shift .ms-sidebar{padding:12px 18px;border-right:0;border-bottom:1px solid #343a2b;gap:0}#my-shift .ms-sidebar>strong,#my-shift .ms-sidebar-help{display:none}#my-shift #ms-menu-toggle{display:flex;justify-content:space-between;width:100%;border:0}#my-shift nav{display:none;padding-top:8px}#my-shift .ms-sidebar[data-open=true] nav{display:flex}#my-shift .ms-main{padding:22px 18px}#my-shift .ms-panel{padding:22px}#my-shift .ms-counts{grid-template-columns:1fr}#my-shift .ms-card{padding:20px}#my-shift h1{font-size:26px}#my-shift .ms-toolbar{flex-wrap:wrap}#my-shift dl{grid-template-columns:1fr}#my-shift input{font-size:16px!important}}

styles./assets/member-experience/member-details:
#memberDetailsPanel{box-sizing:border-box;max-width:920px;width:100%;margin:0 auto 32px;padding:28px;border:1px solid #707762;border-radius:16px;background:#e7e3da;color:#050505;font-family:inherit}
#memberDetailsPanel *,#memberDetailsPanel *:before,#memberDetailsPanel *:after{box-sizing:border-box}
#memberDetailsPanel :is(h2,h3,p,label,legend,small,span){color:inherit;-webkit-text-fill-color:currentColor}
#memberDetailsPanel h2{font-size:32px;line-height:1.15;margin:8px 0 12px;font-family:inherit;letter-spacing:-.03em}
#memberDetailsPanel h3{font-size:21px;line-height:1.3;margin:6px 0 16px;font-family:inherit}
#memberDetailsPanel p{line-height:1.5;font-size:16px;overflow-wrap:anywhere}
#memberDetailsPanel .eyebrow{font-size:11px;letter-spacing:.12em;font-weight:800}
#memberDetailsPanel .md-notice{border-left:3px solid #707762;padding:10px 14px;margin:18px 0 24px}
#memberDetailsPanel a{color:#050505;text-decoration:underline;overflow-wrap:anywhere}
#memberDetailsPanel fieldset{margin:0;padding:0;border:0;min-width:0}
#memberDetailsPanel label{display:block;font-size:15px;font-weight:700;margin:0 0 16px}
#memberDetailsPanel :is(input,select){display:block;max-width:100%;width:100%;min-height:48px;margin:8px 0 0;padding:12px;border:1px solid #707762;border-radius:8px;background:#e7e3da;color:#050505;font:400 16px/1.3 Arial,sans-serif;-webkit-text-fill-color:#050505}
#memberDetailsPanel input[readonly]{border-style:dashed}
#memberDetailsPanel input[type=hidden]{display:none}
#memberDetailsPanel .md-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 18px}
#memberDetailsPanel .md-section{padding-top:22px;margin-top:20px;border-top:1px solid #707762}
#memberDetailsPanel .md-postcode{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:end}
#memberDetailsPanel .md-postcode button{margin-bottom:16px}
#memberDetailsPanel .md-help{font-size:14px;line-height:1.5;margin:0 0 18px}
#memberDetailsPanel .md-optional{font-size:14px;font-weight:400}
#memberDetailsPanel button{min-height:48px;max-width:100%;margin:0;padding:12px 18px;border:1px solid #050505;border-radius:8px;background:#050505;color:#e7e3da;-webkit-text-fill-color:currentColor;font:700 16px/1.4 Arial,sans-serif;cursor:pointer}
#memberDetailsPanel button.md-secondary{background:transparent;color:#050505}
#memberDetailsPanel button:disabled{opacity:.6;cursor:not-allowed}
#memberDetailsPanel :is(input,select,button,a):focus-visible{outline:3px solid #050505;outline-offset:3px}
#memberDetailsPanel .md-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:24px}
#memberDetailsPanel #memberDetailsStatus{min-height:24px;font-weight:700;margin-bottom:0}
#memberDetailsPanel .md-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
/* Retained theme styles use important rules. Define both sides of the colour
   pair only on this new card; never recolour the shared shell or old settings. */
html body[data-member-page="settings"] #memberDetailsPanel{background:#050505!important;color:#e7e3da!important}
html body[data-member-page="settings"] #memberDetailsPanel :is(h2,h3,p,label,legend,small,span,a){color:#e7e3da!important;-webkit-text-fill-color:#e7e3da!important}
html body[data-member-page="settings"] #memberDetailsPanel :is(input,select){background:#e7e3da!important;color:#050505!important;-webkit-text-fill-color:#050505!important}
html body[data-member-page="settings"] #memberDetailsPanel button{background:#e7e3da!important;color:#050505!important;-webkit-text-fill-color:#050505!important;border-color:#707762!important;opacity:1!important}
html body[data-member-page="settings"] #memberDetailsPanel button:disabled{border-style:dashed!important;cursor:not-allowed}
html body[data-member-page="settings"] #memberDetailsPanel :is(input,select,button,a):focus-visible{outline-color:#e7e3da!important;box-shadow:none!important}
#memberDetailsPanel [hidden]{display:none!important}
@media(max-width:600px){#memberDetailsPanel{padding:20px 16px}#memberDetailsPanel h2{font-size:28px}#memberDetailsPanel .md-grid{grid-template-columns:1fr}#memberDetailsPanel .md-postcode{grid-template-columns:1fr;gap:0}#memberDetailsPanel .md-actions>button,#memberDetailsPanel .md-postcode button{width:100%}}

scripts./assets/member-experience/my-shift.mjs:
(()=>{
'use strict';
const root=document.getElementById('my-shift');if(!root)return;
const $=id=>root.querySelector('#'+id),node=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=String(text??'');return e;};
const names={overview:'Overview',profile:'My profile',health:'Health record',orders:'My orders',prescriptions:'Prescriptions',documents:'My documents',updates:'Care updates',consultations:'Consultations',account:'Account & privacy',detail:'Order details'};
let epoch=0,busy=false,ended=false,controller,records=[],treatments=[],shop=[],currentUser=null;
const money=(value,currency='GBP')=>{if(value===null||value===undefined||value===''||!Number.isFinite(Number(value)))return 'Not confirmed';try{return new Intl.NumberFormat('en-GB',{style:'currency',currency}).format(Number(value)/100)}catch{return 'Not confirmed'}};
const stamp=value=>{const d=new Date(value);return value&&Number.isFinite(d.getTime())?new Intl.DateTimeFormat('en-GB',{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/London'}).format(d)+' UK time':'Date not recorded';};
const title=value=>String(value||'Awaiting update').replaceAll('_',' ');
const needs=o=>!!(o.clarificationRequired||o.clinicalIntakeRequired||o.journeySetupRequired);
function link(text,path){const a=node('a',text);a.href=path;a.className='ms-link';return a;}
function card(heading,copy){const c=node('article');c.className='ms-card';if(heading)c.append(node('h2',heading));if(copy)c.append(node('p',copy));return c;}
function button(text,fn){const b=node('button',text);b.type='button';b.onclick=fn;return b;}
function show(view){if(!names[view])view='overview';root.querySelectorAll('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==view);root.querySelectorAll('[data-view]').forEach(b=>{if(b.dataset.view===(view==='detail'?'orders':view))b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('ms-breadcrumb').textContent='MY SHIFT / '+names[view].toUpperCase();$('ms-menu-toggle').textContent=names[view]+' · Menu ▾';$('ms-menu-toggle').setAttribute('aria-expanded','false');root.querySelector('.ms-sidebar').dataset.open='false';if(view!=='detail'&&location.hash!=='#'+view)history.replaceState(null,'','#'+view);}
function clear(){currentUser=null;records=[];treatments=[];shop=[];for(const id of ['ms-activity','ms-counts','ms-actions','ms-current','ms-orders','ms-prescriptions','ms-documents','ms-updates','ms-health','ms-detail'])$(id).replaceChildren();$('ms-member').textContent='My Shift';$('ms-greeting').textContent='Your account. Your care.';$('ms-motion').hidden=true;$('ms-nav-count').hidden=true;const form=document.getElementById('memberDetailsForm');if(form){form.reset();const field=document.getElementById('memberDetailsFields');if(field)field.disabled=true;}}
function expire(){ended=true;++epoch;controller?.abort();clear();document.body.dataset.memberSession='signed-out';const box=document.getElementById('memberSessionStatus');if(box){box.replaceChildren(node('p','Sign in to open your private My Shift account.'),link('Sign in','/member-login?returnTo=%2Fmember%2Fmy-shift'));box.hidden=false;}}
async function read(path){const r=await fetch(path,{credentials:'include',cache:'no-store',signal:controller.signal});if(r.status===401){expire();throw Error('signed-out');}const data=await r.json().catch(()=>null);if(!r.ok||!data)throw Error('unavailable');return data;}
function nextStep(o){if(o.clarificationRequired)return ['Read request & respond','/member/dashboard#today','The clinical team needs more information. Open the secure request to read their questions and respond.'];if(o.clinicalIntakeRequired)return ['Complete clinical checks','/treatment-assessment?'+new URLSearchParams({order:o.orderNumber||'',variant:String(o.variantId||'')}),'Complete the assessment so the clinical team can review your request.'];if(o.journeySetupRequired)return ['Set up My Timber','/member/dashboard#journey','Set your starting point for ongoing support.'];return ['Open treatment log','/member/treatment','No action is currently recorded from you.'];}
function orderCard(o,detail=false){const c=card([o.medicineName,o.strengthLabel].filter(Boolean).join(' · ')||'Treatment request'),head=node('div');head.className='ms-cardhead';const badge=node('span',needs(o)?'ACTION NEEDED':o.headline||title(o.clinicalStatus));badge.className='ms-badge';head.append(node('strong',o.orderNumber),badge);c.prepend(head);c.append(node('p',o.message||''),node('p','Order updated: '+stamp(o.updatedAt)));if(needs(o)){const a=card('Your next step',nextStep(o)[2]);a.classList.add('ms-attention');a.append(link(...nextStep(o).slice(0,2)));c.append(a);}if(detail){const dl=node('dl');for(const[k,v]of [['Placed',stamp(o.createdAt)],['Total',money(o.totalPence,o.currency)],['Payment',title(o.paymentStatus)],['Clinical status',o.headline||title(o.clinicalStatus)]])dl.append(node('dt',k),node('dd',v));c.append(dl,node('p','Clinical approval does not by itself confirm prescription issue, pharmacy acceptance or dispatch. These require separate confirmation from the responsible service.'));}else c.append(button('View order →',()=>{$('ms-detail').replaceChildren(node('h1','Order '+o.orderNumber),orderCard(o,true));show('detail');}));return c;}
function renderOrders(){for(const id of ['ms-current','ms-orders'])$(id).replaceChildren();for(const o of treatments){$('ms-orders').append(orderCard(o));if(!['fulfilled','refunded','declined'].includes(o.clinicalStatus))$('ms-current').append(orderCard(o));}for(const o of shop){const c=card('Order '+o.order_number,title(o.status));c.append(node('p','Placed: '+stamp(o.created_at)),node('p','Total: '+money(o.total_pence,o.currency)));if(Array.isArray(o.items)){const ul=node('ul');for(const item of o.items)ul.append(node('li',[item.product_name,item.colour,item.size,'Qty '+(item.quantity||1)].filter(Boolean).join(' · ')));c.append(ul);}if(o.tracking_reference)c.append(node('p','Tracking reference: '+o.tracking_reference));if(o.tracking_url){try{const u=new URL(o.tracking_url);if(u.protocol==='https:'&&!u.username&&!u.password){const a=link('Track delivery',u.href);a.target='_blank';a.rel='noopener noreferrer';c.append(a);}}catch{}}$('ms-orders').append(c);}if(!$('ms-current').childElementCount)$('ms-current').append(card('No current treatment orders',treatments.length?'Your past orders remain in My orders.':'Confirmed treatment orders will appear here.'));if(!$('ms-orders').childElementCount)$('ms-orders').append(card('No orders recorded','Your order history will appear here after you place an order.'));
 $('ms-actions').replaceChildren();for(const o of treatments.filter(needs)){const c=card('Action needed · '+o.orderNumber,nextStep(o)[2]);c.classList.add('ms-attention');c.append(link(...nextStep(o).slice(0,2)));$('ms-actions').append(c);}const count=treatments.filter(needs).length;$('ms-motion').hidden=!count;$('ms-nav-count').hidden=!count;$('ms-nav-count').textContent=String(count);
 $('ms-counts').replaceChildren();for(const[label,value,copy,attention]of [['Needs your attention',count,count?'Request waiting for you':'Nothing to action',!!count],['Treatment orders',treatments.length,'Confirmed order records',false],['Shop orders',shop.length,'Your purchase history',false]]){const c=node('div');c.className='ms-stat'+(attention?' ms-attention':'');c.append(node('span',label),node('strong',value),node('small',copy));$('ms-counts').append(c);}
 const activity=[...treatments.map(o=>({at:o.updatedAt||o.createdAt,label:o.orderNumber+' · '+(o.headline||title(o.clinicalStatus))})),...shop.map(o=>({at:o.updated_at||o.created_at,label:o.order_number+' · '+title(o.status)}))].sort((a,b)=>(Date.parse(b.at)||0)-(Date.parse(a.at)||0));$('ms-activity').replaceChildren();for(const e of activity.slice(0,6)){const li=node('li');li.append(node('strong',e.label),node('small',stamp(e.at)));$('ms-activity').append(li);}if(!activity.length)$('ms-activity').append(node('li','No recent order activity recorded.'));
 $('ms-updates').replaceChildren();for(const o of treatments){const c=card(o.orderNumber,o.message||o.headline||title(o.clinicalStatus));c.append(node('p','Order updated: '+stamp(o.updatedAt)));if(needs(o))c.append(link(...nextStep(o).slice(0,2)));$('ms-updates').append(c);}if(!treatments.length)$('ms-updates').append(card('No clinical updates recorded','Confirmed care updates will appear here.'));
 $('ms-prescriptions').replaceChildren(card('Prescription documents are not connected here','A treatment order or clinical approval is not proof of an issued prescription. For a copy of your prescription or pharmacy confirmation, contact your clinical service.'),link('Get help','/help'));
}
function unavailable(id,heading,copy){$(id).replaceChildren(card(heading,copy));}
async function load(){if(busy||ended)return;busy=true;const captured=++epoch;controller=new AbortController();const timer=setTimeout(()=>controller.abort(),15000);$('ms-refresh').disabled=true;$('ms-status').textContent='Checking your account…';clear();
 try{const me=await read('/v1/me');if(!me.user?.id)throw Error('session');if(captured!==epoch||ended)return;currentUser=String(me.user.id);
 const results=await Promise.allSettled([read('/v1/member/details'),read('/v1/treatment/orders'),read('/v1/commerce/orders'),read('/v1/member/clinical-records'),read('/v1/member/treatment/week?sources=progress')]);if(captured!==epoch||ended)return;
 let partial=false;const take=i=>results[i].status==='fulfilled'?results[i].value:null,p=take(0)?.details;if(p){const name=[p.firstName,p.lastName].filter(Boolean).join(' ');$('ms-member').textContent=name||'My Shift';$('ms-greeting').textContent=p.firstName?'Welcome back, '+p.firstName+'.':'Welcome back.';}
 const treatmentData=take(1),shopData=take(2);if(treatmentData?.ok===true&&Array.isArray(treatmentData.orders))treatments=treatmentData.orders;else partial=true;if(shopData?.ok===true&&Array.isArray(shopData.orders))shop=shopData.orders;else partial=true;renderOrders();if(!treatmentData?.ok){for(const id of ['ms-current','ms-updates','ms-actions'])unavailable(id,'Treatment updates could not load','Refresh to try again. An unavailable service does not mean there is nothing to action.');$('ms-counts').replaceChildren();}if(!shopData?.ok)$('ms-orders').append(card('Shop orders could not load','Refresh to try again. Your records have not changed.'));
 const clinical=take(3);if(Array.isArray(clinical?.records)){records=clinical.records;$('ms-documents').replaceChildren();for(const r of records){const c=card(r.order_number||'Treatment assessment',title(r.status));c.append(link('Open secure assessment & documents','/treatment-assessment?'+new URLSearchParams({record:r.id})));$('ms-documents').append(c);}if(!records.length)$('ms-documents').append(card('No saved assessments','Documents attached to your assessments will be listed here.'));}else unavailable('ms-documents','Clinical document service is not available here','No document status can be confirmed. Contact SHIFT if you have been asked for more information.');
 const week=take(4)?.week;$('ms-health').replaceChildren();if(week?.context?.progress){const rows=week.context.progress;for(const r of rows.slice(0,10)){const c=card('Recorded '+r.recorded_on,'Source: your My Timber progress log · Member-reported, not independent clinical verification.');for(const [key,label,unit]of [['weight_kg','Weight','kg'],['waist_cm','Waist','cm'],['systolic','Systolic blood pressure','mmHg'],['diastolic','Diastolic blood pressure','mmHg']])if(r[key]!==null&&r[key]!==undefined)c.append(node('p',label+': '+r[key]+' '+unit));$('ms-health').append(c);}if(!rows.length)$('ms-health').append(card('No measurements in this period','Your recorded progress readings will appear here when tracking is enabled.'));}else unavailable('ms-health','Measurements are not available','Tracking may be off, paused or temporarily unavailable. Your existing My Timber records and choices have not changed.');
 $('ms-status').textContent=partial?'Some order services could not load. Refresh to try again.':'Order updates checked · '+stamp(new Date().toISOString());
 }catch{if(captured===epoch&&!ended){clear();$('ms-status').textContent='We could not confirm your account records. Refresh to try again.';}}finally{clearTimeout(timer);busy=false;$('ms-refresh').disabled=false;}}
